const body = $input.first().json.body || $input.first().json;
const isTextMsg = body.event_name === 'user_send_text';
return [{
  json: {
    isTextMsg,
    zaloUserId: (body.sender && body.sender.id) || null,
    oaId: (body.recipient && body.recipient.id) || null,
    userMessage: (body.message && body.message.text) || ''
  }
}];

const raw = $input.first().json.data || $input.first().json.body || $input.first().json;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
const blocks = text.split('---');
const qaList = [];
for (const block of blocks) {
  const qMatch = block.match(/❓\s*CÂU HỎI:\s*([\s\S]*?)(?:\n✅|$)/);
  const aMatch = block.match(/✅\s*TRẢ LỜI:\s*([\s\S]*)/);
  if (qMatch && aMatch) {
    const question = qMatch[1].trim();
    const answer = aMatch[1].trim();
    const needExpert = answer.includes('CẦN CHUYÊN GIA');
    qaList.push({ question, answer, needExpert });
  }
}
const prev = $('Loc chi tin nhan text').first().json;
return [{ json: { qaList, userMessage: prev.userMessage, zaloUserId: prev.zaloUserId } }];

const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
const zaloUserId = $json.zaloUserId;
const session = staticData.sessions[zaloUserId] || [];
return [{ json: Object.assign({}, $json, { sessionHistory: session }) }];

let aiText = '';
try {
  aiText = $input.first().json.content[0].text;
} catch (e) {}
let ai;
try {
  const match = aiText.match(/\{[\s\S]*\}/);
  ai = JSON.parse(match ? match[0] : aiText);
} catch (e) {
  ai = { intent: 'other', matched: false, needExpert: true, answer: null, matchedQuestion: null };
}
const prev = $('Lay lich su phien').first().json;
return [{ json: Object.assign({}, prev, { ai }) }];

const staticData = $getWorkflowStaticData('global');
const zaloUserId = $json.zaloUserId;
const ai = $json.ai || {};
const session = staticData.sessions[zaloUserId] || [];
session.push({ q: $json.userMessage, a: ai.answer || null, matched: !!ai.matched, ts: new Date().toISOString() });
staticData.sessions[zaloUserId] = session.slice(-10);

let route = 'ESCALATE';
if (ai.intent === 'closing_satisfied') {
  route = 'CLOSE_SESSION';
} else if (ai.matched && !ai.needExpert) {
  route = 'AUTO_REPLY';
}

return [{ json: Object.assign({}, $json, { route }) }];

const staticData = $getWorkflowStaticData('global');
const zaloUserId = $json.zaloUserId;
const session = staticData.sessions[zaloUserId] || [];
const lines = session.map((s, i) => (i + 1) + '. Hoi: ' + s.q + '
   Dap: ' + (s.a || '(chuyen sep tra loi)')).join('
');
const report = 'Da cham soc xong khach hang
Zalo ID: ' + zaloUserId + '

Tom tat trao doi:
' + lines + '

Ket qua: Khach xac nhan hai long, khong con thac mac.';
return [{ json: Object.assign({}, $json, { report }) }];

const staticData = $getWorkflowStaticData('global');
if (staticData.sessions) {
  delete staticData.sessions[$json.zaloUserId];
}
return [{ json: { done: true } }];

